          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) {
        // each moved claim became the sheet's newest in turn, so the last moved is listed first
        const moved = new Set(done.claims.map((c) => c.id));
        this.claims.update((cs) => [...done.claims].reverse().concat(cs.filter((c) => !moved.has(c.id))));
        this.selected.set(new Set());
      }
      return { reassigned: done.reassigned, refused: done.refused };
    } catch (e) {
      return failed('reassign', e).replace(' claim', ' claims');
    }
  }

  /** Re-date the chosen claims to one date together, the server re-dating them in list order as a single
   *  re-date would and leaving each that cannot be re-dated as it is; a blank date is the sheet's today.
   *  How many were re-dated and refused, or an error message. */
  async bulkRedate(date: string): Promise<{ redated: number; refused: number } | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    const claimIds = [...this.selected()];
    if (claimIds.length === 0) return 'Select the claims to re-date.';
    if (date.trim() !== '' && !isDate(date.trim())) return 'Enter the new date as YYYY-MM-DD.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ redated: number; refused: number; claims: Claim[] }>(
          `${this.url(sid)}/claims/bulk-redate`,
          { claimIds, date: date.trim() === '' ? null : date.trim() },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) {
        const byId = new Map(done.claims.map((c) => [c.id, c]));
        this.claims.update((cs) => cs.map((c) => byId.get(c.id) ?? c));
        this.selected.set(new Set());
      }
      return { redated: done.redated, refused: done.refused };
    } catch (e) {
      return failed('re-date', e).replace(' claim', ' claims');
    }
  }

  private check(f: ClaimFields): string | null {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!/^-?\d+(\.\d{1,2})?$/.test(f.amount.trim())) return 'Enter an amount with up to two decimals.';
    if (f.date.trim() && !isDate(f.date.trim())) return 'Enter a date as YYYY-MM-DD.';
    const corrects = f.corrects.trim();
    if (corrects.length > 220) return 'Enter the number of the claim it corrects.';
    if (f.ref.trim().length > 200) return 'Enter a reference of up to 200 characters.';
    if (f.tags.length > 2000) return 'Enter tags of up to 2000 characters.';
    if (f.amount.trim().startsWith('-') && !corrects) {
      return 'A negative amount is a correction: name the number of the settled claim it corrects.';
    }
    return null;
  }

  private body(f: ClaimFields): {
    amount: string;

    /** Move the chosen claims to a person together in list order (people in the order they were added, each
     *  person's claims newest first), each as a single reassign by the user would; one that cannot be moved is
     *  left as it is and counted as refused, as is one not on the sheet. */
    @Transactional
    public BulkReassigned bulkReassign(String sheetId, String user, Collection<Long> claimIds, long toPersonId) {
        Set<Long> chosen = new HashSet<>(claimIds);
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            return new BulkReassigned(0, chosen.size(), List.of());
        }
        List<Claim> moved = new ArrayList<>();
        for (Claim claim : inListOrder(sheetId, chosen)) {
            try {
                moved.add(move(sheetId, user, claim.getId(), toPersonId, false));
            } catch (ClaimReassignException | PersonRetiredException | PersonNotFoundException
                    | PeriodClosedException | ClaimNotFoundException e) {
                // refused: left as it is
            }
        }
        return new BulkReassigned(moved.size(), chosen.size() - moved.size(), moved);
    }

    /** What a bulk re-date did: how many it re-dated and refused, and the claims it re-dated, in the order re-dated. */
    public record BulkRedated(int redated, int refused, List<Claim> claims) {
    }

    /** Re-date the chosen claims to one date together in list order (people by their position, each
     *  person's claims newest first), each as a single re-date by the user would; one that cannot be re-dated
     *  is left as it is and counted as refused, as is one not on the sheet. */
    @Transactional
    public BulkRedated bulkRedate(String sheetId, String user, Collection<Long> claimIds, LocalDate date) {
        Set<Long> chosen = new HashSet<>(claimIds);
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            return new BulkRedated(0, chosen.size(), List.of());
        }
        List<Claim> redated = new ArrayList<>();
        for (Claim claim : inListOrder(sheetId, chosen)) {
            try {
                redated.add(redate(sheetId, user, claim.getId(), date));
            } catch (ClaimRedateException | PersonRetiredException | PersonNotFoundException
                    | PeriodClosedException | ClaimNotFoundException e) {
                // refused: left as it is
            }
        }
        return new BulkRedated(redated.size(), chosen.size() - redated.size(), redated);
    }

    /** The sheet's chosen claims in list order: people by their position, each person's claims
     *  newest first. */
    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
        Map<Long, Integer> personOrder = new HashMap<>();
        return new BulkReassignView(done.reassigned(), done.refused(),
                done.claims().stream().map(ClaimView::of).toList());
    }

    /** The claims chosen to re-date together, and the date they are re-dated to; a missing date is the sheet's today. */
    public record BulkRedateRequest(@NotNull @Size(max = 10000) List<@NotNull Long> claimIds, LocalDate date) {
    }

    /** How many a bulk re-date re-dated and refused, and the claims it re-dated. */
    public record BulkRedateView(int redated, int refused, List<ClaimView> claims) {
    }

    /** Re-date the chosen claims together, in list order; each that cannot be re-dated is left as it is. */
    @PostMapping("/claims/bulk-redate")
    public BulkRedateView bulkRedate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid BulkRedateRequest request) {
        ClaimService.BulkRedated done = service.bulkRedate(sheetId.trim(), user.trim(), request.claimIds(),
                request.date());
        return new BulkRedateView(done.redated(), done.refused(),
                done.claims().stream().map(ClaimView::of).toList());
    }

